import bisect


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _nonempty_text(value):
    return isinstance(value, str) and value.strip() != ""


def _compatible(a, b, cooldown):
    if a["start"] <= b["start"]:
        return a["end"] + cooldown <= b["start"]
    return b["end"] + cooldown <= a["start"]


def _max_value(intervals, cooldown):
    if not intervals:
        return 0
    idx = sorted(
        range(len(intervals)),
        key=lambda i: (intervals[i]["end"], intervals[i]["start"], intervals[i]["id"]),
    )
    m = len(idx)
    ends = [intervals[i]["end"] for i in idx]
    starts = [intervals[i]["start"] for i in idx]
    values = [intervals[i]["value"] for i in idx]
    dp = [0] * m
    for i in range(m):
        limit = starts[i] - cooldown
        j = bisect.bisect_right(ends, limit) - 1
        take = values[i] + (dp[j] if j >= 0 else 0)
        skip = dp[i - 1] if i > 0 else 0
        dp[i] = take if take > skip else skip
    return dp[-1]


def _oracle(items_by_id, required, forbidden, target, cooldown):
    req = [items_by_id[i] for i in required]
    for x in range(len(req)):
        for y in range(x + 1, len(req)):
            if not _compatible(req[x], req[y], cooldown):
                return False
    base = sum(it["value"] for it in req)
    candidates = []
    for iid, it in items_by_id.items():
        if iid in required or iid in forbidden:
            continue
        ok = True
        for r in req:
            if not _compatible(it, r, cooldown):
                ok = False
                break
        if ok:
            candidates.append(it)
    return base + _max_value(candidates, cooldown) == target


