    if not isinstance(payloads, list) or not payloads:
        raise ValueError("missing input payloads")
    raw = payloads[0]
    if not isinstance(raw, dict):
        raise ValueError("first payload must be an object")
    windows = raw.get("windows")
    if not isinstance(windows, list):
        raise ValueError("windows must be a list")

    cooldown = contract.get("cooldown")
    if not _is_int(cooldown) or cooldown < 0:
        raise ValueError("cooldown must be a non-negative int")

    items = []
    seen = set()
    for w in windows:
        if not isinstance(w, dict):
            raise ValueError("window must be an object")
        for key in ("id", "start", "end", "value"):
            if key not in w:
                raise ValueError("window missing field: " + key)
        wid = w["id"]
        if not _nonempty_text(wid):
            raise ValueError("window id must be non-empty text")
        wid = wid.strip()
        if wid in seen:
            raise ValueError("duplicate window id: " + wid)
        seen.add(wid)
        start = w["start"]
        end = w["end"]
        value = w["value"]
        if not _is_int(start) or start < 0:
            raise ValueError("window start must be an int >= 0")
        if not _is_int(end) or end <= start:
            raise ValueError("window end must be an int > start")
        if not _is_int(value):
            raise ValueError("window value must be an int")
        items.append({"id": wid, "start": start, "end": end, "value": value})

    items_by_id = {it["id"]: it for it in items}
    best_value = _max_value(items, cooldown)

    if best_value == 0:
        selected = []
    else:
        ids_sorted = sorted(items_by_id)
        required = set()
        selected = []
        while True:
            chosen = None
            for x in ids_sorted:
                if x in required:
                    continue
                if required and x < max(required):
                    continue
                forbidden = {y for y in ids_sorted if y < x and y not in required}
