                raise ValueError("unknown dependency: " + d)

    adj = {nid: set() for nid in node_ids}
    for nid in node_ids:
        for d in deps_raw[nid]:
            adj[d].add(nid)

    blocked = False
    for payload in payloads[1:]:
        res = _unwrap(payload)
        if not isinstance(res, dict) or "feasible" not in res:
            continue
        feas = res["feasible"]
        if feas is False:
            blocked = True
            break
        if feas is not True:
            raise ValueError("feasible must be a boolean")
        assignments = res.get("assignments")
        if not isinstance(assignments, list):
            raise ValueError("assignments must be a list")
        worker_jobs = defaultdict(list)
        for a in assignments:
            if not isinstance(a, dict):
                raise ValueError("assignment must be an object")
            job = a.get("job")
            worker = a.get("worker")
            if not isinstance(job, str) or not isinstance(worker, str):
                raise ValueError("assignment job/worker must be strings")
            if job not in id_set:
                raise ValueError("unknown assigned job: " + job)
            worker_jobs[worker].append(job)
