    for nid in node_ids:
        for s in adj[nid]:
            preds[s].add(nid)

    in_degree = {nid: len(preds[nid]) for nid in node_ids}
    waves = []
    ready = sorted([nid for nid in node_ids if in_degree[nid] == 0])
    processed = 0
    while ready:
        waves.append(list(ready))
        next_ready = []
        for nid in ready:
            processed += 1
            for s in adj[nid]:
                in_degree[s] -= 1
                if in_degree[s] == 0:
                    next_ready.append(s)
        ready = sorted(next_ready)
    if processed != len(node_ids):
        raise ValueError("dependency cycle detected")

