    path = {}
    for wave in waves:
        for nid in wave:
            pre = preds[nid]
            if not pre:
                finish[nid] = durations[nid]
                path[nid] = [nid]
            else:
                m = max(finish[d] for d in pre)
                best = None
                for d in pre:
                    if finish[d] == m:
                        if best is None or path[d] < path[best]:
