    earliest_finish = {nid: finish[nid] for nid in node_ids}
    return {
        "name": contract["name"],
        "result": {
            "blocked": False,
            "waves": waves,
            "critical_path": critical_path,
            "makespan": makespan,
            "earliest_finish": earliest_finish,
        },
    }

