import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def contracts():
    result = []
    for p in sorted(ROOT.rglob("contract.json")):
        if "outputs" in p.relative_to(ROOT).parts:
            continue
        result.append(p)
    return result


def main():
    comps = {}
    for p in contracts():
        c = json.loads(p.read_text(encoding="utf-8"))
        comps[c["name"]] = {"contract_path": p, "contract": c}

    output_owner = {}
    for name, info in comps.items():
        output_owner[info["contract"]["output"]] = name

    deps = {name: set() for name in comps}
    for name, info in comps.items():
        for inp in info["contract"]["inputs"]:
            if inp in output_owner:
                deps[name].add(output_owner[inp])

    state = {}
    order = []

    def visit(name):
        if name in state:
            if state[name] == "visiting":
                raise ValueError("cycle in contract dependencies")
            return
        state[name] = "visiting"
        for d in sorted(deps[name]):
            visit(d)
        state[name] = "done"
        order.append(name)

    for name in sorted(comps):
        visit(name)

    for name in order:
        render = comps[name]["contract_path"].with_name("render.py")
        subprocess.run([sys.executable, str(render)], cwd=ROOT, check=True)

    subprocess.run([sys.executable, str(ROOT / "integrate.py")], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / "final_report.py")], cwd=ROOT, check=True)


if __name__ == "__main__":
    main()

