import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _write_json(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(data, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False)
        + "\n",
        encoding="utf-8",
    )


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def main():
    core_path = ROOT / "outputs" / "core_manifest.json"
    core_object = json.loads(core_path.read_text(encoding="utf-8"))
    components = core_object.get("components")
    if not isinstance(components, dict):
        raise ValueError("core_manifest must contain a components object")

    serialized = json.dumps(
        core_object,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    sha256 = hashlib.sha256(serialized).hexdigest()

    attention = set()
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            attention.add(name)
        if result.get("feasible") is False:
            attention.add(name)
        if result.get("compatible") is False:
            attention.add(name)
        if "deny" in result and _is_number(result["deny"]) and result["deny"] > 0:
            attention.add(name)
        if (
            "score_total" in result
            and _is_number(result["score_total"])
            and result["score_total"] >= 20
        ):
            attention.add(name)

    report = {
        "title": "租户配额再平衡",
        "component_count": len(components),
        "sha256": sha256,
        "attention": sorted(attention),
    }
    _write_json(ROOT / "outputs" / "final_report.json", report)


if __name__ == "__main__":
    main()

